  g.links.forEach((l, i) => { const gr = defs.append("linearGradient").attr("id", "lg" + i).attr("gradientUnits", "userSpaceOnUse").attr("x1", l.source.x1).attr("x2", l.target.x0);
    gr.append("stop").attr("offset", 0).attr("stop-color", l.source.c); gr.append("stop").attr("offset", 1).attr("stop-color", l.target.c); });
  const linkPaths = svg.append("g").attr("fill", "none").selectAll("path").data(g.links).join("path")
