  const nodeG = svg.append("g").selectAll("g").data(g.nodes).join("g");
  nodeG.append("rect").attr("x", d => d.x0).attr("y", d => d.y0).attr("width", d => d.x1 - d.x0).attr("height", d => Math.max(2, d.y1 - d.y0)).attr("rx", 3).attr("fill", d => d.c)
