/* =========================================================== 08 STREAM */
const stream = { play() {} };
function streamScene() {
  const S = D.stream, kinds = Object.keys(S.histogram), color = { CHECKOUT: C.violet, INVOICE: C.gold, PAYMENT: C.cyan };
  $("#counters").innerHTML = kinds.map(k => `<div class="panel counter-tile" style="border-color:${color[k]}33"><span class="k-lbl" style="font:600 11px var(--f-mono);letter-spacing:.12em;color:var(--muted)">${k}</span><b class="num" data-k="${k}">${fmtI(S.kinds[k])}</b><span class="sub">Fabric EH_MIZAN: ${fmtI(S.fabric_rows[k])}</span></div>`).join("") +
    `<div class="panel counter-tile"><span style="font:600 11px var(--f-mono);letter-spacing:.12em;color:var(--muted)">ALERTS</span><b class="num" id="alert-n">${S.alerts.length}</b><span class="sub">Fabric KQL: velocity ${S.fabric_rules.VelocityAlerts} \u00b7 mule ${S.fabric_rules.MuleRingAlerts} \u00b7 SLA ${S.fabric_rules.InvoiceReportingSlaBreaches}</span></div>`;
  const t0 = Date.parse(S.from), t1 = Date.parse(S.to);
  $("#alerts").innerHTML = S.alerts.map((a, i) => `<div class="alert on" data-i="${i}"><div style="display:flex;justify-content:space-between;gap:8px"><span class="pill ${a.rule === "REPORTING_SLA" ? "crit" : "warn"}">${a.rule}</span><span class="when">${riyadh(a.at)}</span></div>
     <div style="margin-top:6px">${a.detail}</div><div class="when">${a.rule === "REPORTING_SLA" ? "invoice " : "token "}${a.key}${a.rule === "REPORTING_SLA" ? "" : "…"}</div></div>`).join("");
  const cv = $("#river"), ctx = cv.getContext("2d"); let head = 1, playing = false, sparks = [];
  const nB = S.histogram[kinds[0]].length, maxB = Math.max(...kinds.flatMap(k => S.histogram[k]));
  function size() { const w = cv.clientWidth, h = 360, dpr = Math.min(devicePixelRatio, 2); cv.width = w * dpr; cv.height = h * dpr; cv.style.height = h + "px"; ctx.setTransform(dpr, 0, 0, dpr, 0, 0); return { w, h }; }
  let Z = size(); new ResizeObserver(() => { Z = size(); }).observe(cv);
  function draw(dt) {
    const { w, h } = Z, padL = 12, padR = 12, laneH = (h - 50) / kinds.length; ctx.clearRect(0, 0, w, h);
    const X = b => padL + b / (nB - 1) * (w - padL - padR);
    kinds.forEach((k, li) => { const cy = 18 + laneH * li + laneH / 2, amp = laneH * .42, arr = S.histogram[k], c = color[k];
      ctx.fillStyle = "rgba(140,160,190,.05)"; ctx.fillRect(padL, cy - amp, w - padL - padR, amp * 2);
      const upto = Math.floor(head * (nB - 1));
      const grad = ctx.createLinearGradient(0, cy - amp, 0, cy + amp); grad.addColorStop(0, c + "00"); grad.addColorStop(.5, c + "cc"); grad.addColorStop(1, c + "00");
      ctx.beginPath(); for (let b = 0; b <= upto; b++) { const v = Math.sqrt(arr[b] / maxB) * amp; b ? ctx.lineTo(X(b), cy - v) : ctx.moveTo(X(b), cy - v); }
      for (let b = upto; b >= 0; b--) { const v = Math.sqrt(arr[b] / maxB) * amp; ctx.lineTo(X(b), cy + v); } ctx.closePath(); ctx.fillStyle = grad; ctx.fill();
      ctx.fillStyle = c; ctx.font = "600 10px IBM Plex Mono, monospace"; ctx.fillText(k, padL + 6, cy - amp + 12);
      if (playing && upto < nB) { const n = Math.min(6, Math.ceil(arr[upto] / maxB * 8)); for (let i = 0; i < n; i++) sparks.push({ x: X(upto), y: cy + (Math.random() - .5) * amp * 1.2, vx: 40 + Math.random() * 120, life: 1, c }); } });
    const hx = padL + head * (w - padL - padR);
    ctx.strokeStyle = "rgba(243,217,156,.8)"; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(hx, 8); ctx.lineTo(hx, h - 30); ctx.stroke();
    sparks = sparks.filter(s => (s.life -= dt * 1.6) > 0); for (const s of sparks) { s.x += s.vx * dt; ctx.globalAlpha = s.life; ctx.fillStyle = s.c; ctx.fillRect(s.x, s.y, 2, 2); } ctx.globalAlpha = 1;
    S.alerts.forEach(a => { const f = (Date.parse(a.at) - t0) / (t1 - t0); if (f > head) return; const ax = padL + f * (w - padL - padR);
      ctx.fillStyle = a.rule === "REPORTING_SLA" ? C.crit : C.warn; ctx.beginPath(); ctx.arc(ax, h - 22, 5, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = ctx.fillStyle; ctx.globalAlpha = .4; ctx.beginPath(); ctx.moveTo(ax, 10); ctx.lineTo(ax, h - 26); ctx.stroke(); ctx.globalAlpha = 1; });
    ctx.fillStyle = C.dim; ctx.font = "10px IBM Plex Mono, monospace"; ctx.fillText(riyadh(S.from), padL, h - 4); ctx.textAlign = "right"; ctx.fillText(riyadh(S.to), w - padR, h - 4); ctx.textAlign = "left";
  }
  let vis = false, lastT = performance.now(); new IntersectionObserver(es => vis = es[0].isIntersecting).observe(cv);
  (function loop(now) { requestAnimationFrame(loop); const dt = Math.min(.05, (now - lastT) / 1000); lastT = now; if (!vis) return;
    if (playing) { head = Math.min(1, head + dt / 11); const cum = k => S.histogram[k].slice(0, Math.floor(head * (nB - 1)) + 1).reduce((a, b) => a + b, 0);
      kinds.forEach(k => $(`[data-k="${k}"]`).textContent = fmtI(head >= 1 ? S.kinds[k] : cum(k)));
      S.alerts.forEach((a, i) => { const on = (Date.parse(a.at) - t0) / (t1 - t0) <= head; const el = $(`.alert[data-i="${i}"]`); if (on && !el.classList.contains("on")) { el.classList.add("on"); window.gsap && gsap.fromTo(el, { x: 30 }, { x: 0, duration: .5, ease: "back.out(2)" }); } });
      $("#alert-n").textContent = S.alerts.filter(a => (Date.parse(a.at) - t0) / (t1 - t0) <= head).length;
      if (head >= 1) playing = false; }
    draw(dt); })(lastT);
  stream.play = () => { if (REDUCED) return; head = 0; playing = true; document.querySelectorAll(".alert").forEach(a => a.classList.remove("on")); };
  $("#stream-play").addEventListener("click", () => stream.play());
}

