  const tc = { TOP_SECRET: C.crit, SECRET: C.warn, CONFIDENTIAL: C.gold, PUBLIC: C.cyan }, order = ["TOP_SECRET", "SECRET", "CONFIDENTIAL", "PUBLIC"];
  const mxT = Math.max(...Object.values(cat.columns));
