  const mx = Math.max(...runs.map(r => r.max_task_ms));
  const nm = { AQE_OFF: "AQE off", AQE_SKEW_JOIN: "AQE skew-join", SALTED_16: "16-bucket salt" }, col = { AQE_OFF: C.crit, AQE_SKEW_JOIN: C.warn, SALTED_16: C.ok };
  $("#race-sub").textContent = `${fmtI(runs[0].rows)} rows · checksum SAR ${fmtH(H(runs[0].sar_checksum))} identical in all runs · compaction ${comp.files_before} → ${comp.files_after} files`;
  $("#race").innerHTML = runs.map(r => `<div class="lane"><span><b style="color:${col[r.run_type]}">${nm[r.run_type]}</b><br><span style="color:var(--dim)">${r.tasks} tasks · ${r.duration_s}s</span></span>
      <div class="track"><div class="med" style="width:${r.median_task_ms / mx * 100}%"></div><div class="max" data-w="${r.max_task_ms / mx}" style="width:${r.max_task_ms / mx * 100}%;background:${col[r.run_type]};box-shadow:0 0 18px ${col[r.run_type]}"></div></div>
      <span class="num">${(r.max_task_ms / 1000).toFixed(1)}s max<br><span style="color:var(--dim)">${(r.median_task_ms / 1000).toFixed(2)}s median</span></span></div>`).join("") +
    `<div class="legend"><span><i style="background:rgba(92,200,255,.5);height:8px"></i>median task</span><span><i style="background:var(--muted);height:8px"></i>slowest task (the straggler)</span></div>`;
  const F = D.fabric, ORDER = ["bronze_land", "silver_build", "mdm_resolve", "zatca_chain", "ai_index", "ndmo_catalog"], jobs = ORDER.filter(k => F.notebook_jobs[k]).map(k => [k, F.notebook_jobs[k]]), tot = jobs.reduce((a, [, j]) => a + j.seconds, 0); let acc = 0;
  $("#fab-cap").textContent = F.capacity;
  $("#gantt").innerHTML = jobs.map(([k, j]) => { const l = acc / tot * 100, w = j.seconds / tot * 100; acc += j.seconds;
    return `<div class="lane"><span>${k}</span><div class="track" style="height:18px"><div class="max" data-l="${l}" style="top:0;bottom:0;left:${l}%;width:${w}%;background:linear-gradient(90deg,var(--gold),var(--gold-hi))"></div></div><span class="num">${j.seconds}s <span class="pill ok" style="padding:1px 5px">&#10003;</span></span></div>`; }).join("");
  $("#fab-dbt").textContent = `${F.dbt_build_WH_MIZAN.pass} pass · ${F.dbt_build_WH_MIZAN.error} error`;
