let lang = "en";
function setLang(next) {
  lang = next; const ar = lang === "ar"; document.documentElement.lang = ar ? "ar" : "en"; document.documentElement.dir = ar ? "rtl" : "ltr";
  const swap = (el, txt) => { if (!el) return; if (el.dataset.en === undefined) el.dataset.en = el.innerHTML; el.innerHTML = ar ? txt : el.dataset.en; };
  rail.querySelectorAll("a").forEach(a => swap(a.querySelector("span"), AR.menu[a.dataset.id] || a.querySelector("span").textContent));
  for (const [id, t] of Object.entries(AR.scenes)) { const sec = document.getElementById(id); if (!sec) continue; swap(sec.querySelector(".scene-head .tag"), t[0]); swap(sec.querySelector(".scene-head h2"), t[1]); }
  swap(document.querySelector(".hero h1"), AR.h1); swap(document.querySelector(".hero .lede"), AR.lede);
  for (const [sel, t] of Object.entries(AR.ui)) document.querySelectorAll(sel).forEach(el => swap(el, t));
  const se = $("#search"); if (se.dataset.enPh === undefined) se.dataset.enPh = se.placeholder; se.placeholder = ar ? AR.search : se.dataset.enPh;
  const mi = $("#flt-mid"); if (mi.dataset.enPh === undefined) mi.dataset.enPh = mi.placeholder; mi.placeholder = ar ? AR.mid : mi.dataset.enPh;
  $("#lang-btn").textContent = ar ? "EN" : "\u0639"; $("#lang-btn").title = ar ? "English" : "\u0627\u0644\u0639\u0631\u0628\u064a\u0629";
  hero.relayout && hero.relayout();
}

/* =========================================================== presenter mode + trace one riyal */
function chromeH() { return parseFloat(getComputedStyle(document.body).getPropertyValue("--chrome")) || 0; }
function tracePerRiyal() {
  const G = H(R.gross); if (G <= 0) return toast("No captures for the current filters");
  const parts = [["refunded", H(R.refunds)], ["acquirer fees", H(R.fees)], ["paid by the bank", H(R.bank)], ["in transit (T+1)", H(R.transit)], ["quarantined", H(R.quarantined)]];
  const raw = parts.map(([, v]) => v * 100 / G), fl = raw.map(Math.floor); let left = 100 - fl.reduce((a, b) => a + b, 0);
  raw.map((v, i) => [v - fl[i], i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (left > 0) { fl[i]++; left--; } });
  goTo("flow"); setTimeout(() => flow.trace && flow.trace(), 700);
  toast(`Of every SAR 1.00 captured: ` + parts.map(([n], i) => `${(fl[i] / 100).toFixed(2)} ${n}`).filter((_, i) => fl[i] > 0).join(" \u00b7 ") + " (largest-remainder rounding to the halala)");
}

